#!/usr/bin/env python3
"""
Round 161b (culprits), 4 October 2026. Needs round 160b.

Old fantasy painting basemap made less dreary.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ["## Round 161b (4 October)\n\nNeeds round 160b. No tiles patch. No app.js?v= bump.\n\n- Owner on 160b: too dreary; muddy crop fields close in, blotchy mouldy\n  landscapes at middle zooms, a dreary purple world view.\n- Old fantasy painting (DUSK) lightened and cooled: lighter moss, umber and\n  slate ramps and a lighter tone curve; colours dulled 12% toward a cool grey\n  (#5F6670) instead of 28% toward grey-violet; height haze, sky, fog and\n  shadows cool grey and slate rather than violet (sky #5C6E80, horizon\n  #CBC8BC, atmosphere 0.45 at the world view); lighter shadows and corners;\n  sea tint lighter; the close-in photograph graded 22% (was 40%).\n- Blotches: the washes were widened at world views (DUSK.loose 2), which\n  smeared continents; now narrower there (0.5 to zoom 4, 0.75 to zoom 7) and\n  the broad strokes thinner and fainter. Looseness far out comes from the\n  broad strokes alone.\n- Checked on real satellite squares (MapLibre's test tiles, zoom 1 and 17)\n  in node; not seen against the live picture.\n"]


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round161b: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 160b" not in h.read_text(encoding="utf-8"):
        sys.exit("round161b: round 160b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round161b: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", check=False)
            sys.exit("round161b: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round161b: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


DIFF = ''

if __name__ == "__main__":
    main()
